  "source": {
    "citation": "Seong-Ho Shinn, Spontaneous Quantum Turbulence in a Newborn Bose-Einstein Condensate via the Kibble-Zurek Mechanism, Physical Review Letters (2026), DOI:10.1103/b16v-hwp2",
    "journal_doi": "10.1103/b16v-hwp2",
    "arxiv_versioned_id": "2506.21670v3"
  },
  "paper_scope": "The paper studies spontaneous quantum turbulence (SQT) in a 2D Bose-Einstein condensate formed by a thermal quench, using stochastic projected Gross-Pitaevskii simulations. It establishes Kibble-Zurek scaling of vortex number and equilibration time, Kolmogorov scaling of the incompressible kinetic energy spectrum, and universal collapse of the incompressible kinetic energy E_i with quench duration tau_Q at two temperatures.",
  "mechanisms": [
    {
      "mechanism_id": "KZ_scaling_Ei",
      "statement": "The incompressible kinetic energy E_i at equilibration scales with quench duration as E_i proportional to tau_Q^{-(1+2 nu)/(1+z nu)}, with mean-field exponents nu=1/2 and z=2 giving E_i proportional to tau_Q^{-1}.",
      "equations": [
        "E_i \\propto \\tau_Q^{-(1+2\\nu)/(1+z\\nu)}",
        "E_i \\propto \\tau_Q^{-1} for \\nu=1/2, z=2"
      ],
      "variable_names": ["E_i", "tau_Q", "nu", "z"],
      "parameters": [
        {
          "name": "nu_critical_exponent",
          "value": 0.5,
          "uncertainty": "source_unspecified",
          "unit": "dimensionless",
          "role": "correlation-length critical exponent",
          "anchors": [
            {
              "line_start": 167,
              "line_end": 167,
              "support": "Using the mean-field values of the critical exponents nu = 1/2 and z = 2"
